 *
 * SPDX-License-Identifier: Apache-2.0
 */

#include <zephyr/kernel.h>
#include <zephyr/sys/atomic.h>
#include <zephyr/sys/p4wq.h>
#include <zephyr/rtio/rtio.h>
#include <zephyr/rtio/work.h>

#define RTIO_WORKQ_STACK_SIZE 1024

#define RTIO_WORKQ_POOL_ITEMS (CONFIG_RTIO_WORKQ_THREADS_POOL + 1)

K_P4WQ_DEFINE(rtio_workq, CONFIG_RTIO_WORKQ_THREADS_POOL, RTIO_WORKQ_STACK_SIZE);

struct rtio_work_req {
	struct k_p4wq_work work;
	struct rtio_iodev_sqe *iodev_sqe;
	rtio_work_handler_t handler;
	atomic_t used;
};

static struct rtio_work_req req_pool[RTIO_WORKQ_POOL_ITEMS];
static atomic_t used_count;

struct rtio_work_req *rtio_work_req_alloc(void)
{
	for (int i = 0; i < RTIO_WORKQ_POOL_ITEMS; i++) {
		if (atomic_cas(&req_pool[i].used, 0, 1)) {
			atomic_inc(&used_count);
			return &req_pool[i];
		}
	}
	return NULL;
}

static void rtio_work_req_free(struct rtio_work_req *req)
{
	atomic_set(&req->used, 0);
	atomic_dec(&used_count);
}

static void p4wq_handler(struct k_p4wq_work *work)
{
	struct rtio_work_req *req = CONTAINER_OF(work, struct rtio_work_req, work);

	if (req->handler && req->iodev_sqe) {
		req->handler(req->iodev_sqe);
	}

	rtio_work_req_free(req);
}

static int32_t rtio_prio_to_thread_prio(uint8_t rtio_prio)
{
	if (rtio_prio >= RTIO_PRIO_HIGH) {
		return CONFIG_RTIO_WORKQ_PRIO_MED - 2;
	} else if (rtio_prio >= RTIO_PRIO_NORM) {
		return CONFIG_RTIO_WORKQ_PRIO_MED;
	} else {
		return CONFIG_RTIO_WORKQ_PRIO_MED + 2;
	}
}

